/* ==========================================================================
   PHILOSOPHIE — Terminale générale, bac 2027 (17 notions)
   ========================================================================== */
{
const { pick, box } = OUT;

/* Construit une fiche de notion à partir de ses éléments */
function notion(o) {
  return {
    court: o.nom, titre: o.nom,
    fiche: `<p>${o.def}</p>
      ${box("Les grands problèmes", "<ul>" + o.problemes.map(p => `<li>${p}</li>`).join("") + "</ul>")}
      <h3>Les positions à connaître</h3>
      <ul>${o.positions.map(([a, t]) => `<li><b>${a}</b> : ${t}</li>`).join("")}</ul>
      ${o.distinctions ? box("Distinctions utiles", o.distinctions, "tip") : ""}
      <h3>Des sujets possibles</h3><ul>${o.sujetsEx.map(s => `<li>${s}</li>`).join("")}</ul>`,
    quiz: o.quiz,
    exos: o.exos.map((e, k) => ({ id: "ph-" + o.id + k, niv: e[3] || 2, titre: "Analyser un sujet de dissertation",
      q: `<p><b>Sujet :</b> ${e[0]}</p><p>Définis les termes, formule une problématique et propose un plan en deux ou trois parties.</p>`,
      c: `<p><b>Problématique :</b> ${e[1]}</p><p><b>Plan possible :</b></p>${e[2]}` })),
  };
}
const plan = (...p) => "<ol>" + p.map(x => `<li>${x}</li>`).join("") + "</ol>";

const NOTIONS = [
notion({ id: "art", nom: "L'art",
  def: "L'art désigne d'abord un savoir-faire (la technique de l'artisan), puis, au sens moderne, la production d'œuvres qui ne visent pas l'utilité mais la <b>beauté</b> ou l'expression. L'œuvre d'art est faite pour être contemplée.",
  problemes: ["L'art imite-t-il la nature ou crée-t-il quelque chose de nouveau ?", "Le beau est-il objectif ou affaire de goût personnel ?", "L'artiste est-il un génie inspiré ou un travailleur ?", "L'art nous détourne-t-il du réel ou nous le fait-il mieux voir ?"],
  positions: [["Platon", "l'art est une imitation d'imitation : il nous éloigne de la vérité des Idées (République, livre X)."], ["Aristote", "l'imitation (mimèsis) est naturelle et source de connaissance ; la tragédie produit une catharsis, une purification des passions."], ["Kant", "le beau est ce qui plaît universellement sans concept ; le jugement de goût est désintéressé. Le génie donne ses règles à l'art."], ["Hegel", "l'art est une manifestation sensible de l'Esprit ; il est supérieur au beau naturel car il est produit par l'esprit."], ["Bergson", "l'artiste dévoile une réalité que nous ne voyons plus, car nous percevons le monde à travers l'utilité et les mots."]],
  distinctions: "Art / technique ; beau / agréable ; artiste / artisan ; œuvre / produit.",
  sujetsEx: ["L'art nous éloigne-t-il de la réalité ?", "Peut-on discuter des goûts ?", "Une œuvre d'art doit-elle être belle ?"],
  quiz: [["Pour Kant, le beau est ce qui plaît…", ["universellement sans concept", "à la majorité", "parce qu'il est utile", "aux seuls experts"], "Le jugement de goût prétend à l'universalité sans pouvoir être démontré."], ["La catharsis est une idée d'…", ["Aristote", "Platon", "Hegel", "Nietzsche"], "La tragédie purifie les passions de pitié et de crainte."], ["Pour Platon, l'art est…", ["une imitation d'imitation, éloignée du vrai", "la plus haute forme de vérité", "une technique utile", "le reflet des Idées"], "Le peintre copie le lit fabriqué par l'artisan, lui-même copie de l'Idée de lit."], ["Selon Bergson, l'artiste…", ["nous fait voir ce que nous ne percevions plus", "copie fidèlement la nature", "invente un monde irréel", "travaille pour l'utilité"], "Nous ne percevons d'ordinaire que ce qui nous est utile."]],
  exos: [["L'art nous détourne-t-il de la réalité ?", "L'art, qui crée des fictions et des apparences, nous éloigne-t-il du réel, ou nous permet-il au contraire de mieux le percevoir ?", plan("Oui, l'art produit des illusions qui détournent du vrai (Platon : imitation d'imitation ; divertissement).", "Mais l'art révèle le réel que notre perception utilitaire masque (Bergson) et donne forme à des vérités humaines (catharsis chez Aristote).", "L'art ne copie ni ne fuit le réel : il en propose une interprétation qui l'enrichit (Hegel : manifestation sensible de l'esprit).")], ["Peut-on discuter des goûts ?", "Si le goût est personnel, toute discussion est-elle vaine, ou le jugement esthétique peut-il prétendre à une forme d'universalité ?", plan("« Des goûts et des couleurs, on ne discute pas » : le goût semble subjectif et lié à l'éducation, au milieu social.", "Pourtant, quand je dis « c'est beau », je prétends que tous devraient l'approuver (Kant : universalité sans concept) : on ne dispute pas (on ne démontre pas), mais on discute.", "La discussion forme le goût : la culture et la comparaison des œuvres permettent un jugement plus éclairé."), 3]] }),
notion({ id: "bonheur", nom: "Le bonheur",
  def: "Le bonheur est un état de satisfaction <b>complète et durable</b>. Il se distingue du plaisir, qui est passager et partiel. Tous les hommes le recherchent, mais ils ne s'accordent pas sur ce qu'il est.",
  problemes: ["Le bonheur dépend-il de nous ou de la chance ?", "Faut-il satisfaire tous ses désirs pour être heureux ?", "Le bonheur est-il un idéal inaccessible ?", "Le bonheur est-il compatible avec la morale ?"],
  positions: [["Aristote", "le bonheur est la fin suprême, recherché pour lui-même ; il réside dans l'activité conforme à la vertu, la plus haute étant la contemplation."], ["Épicure", "le bonheur est l'ataraxie (absence de trouble de l'âme) et l'aponie (absence de douleur du corps) ; il faut trier les désirs naturels et nécessaires."], ["Les stoïciens (Épictète)", "distinguer ce qui dépend de nous (nos jugements) de ce qui n'en dépend pas ; le bonheur est dans la vertu et l'acceptation."], ["Kant", "le bonheur est un idéal de l'imagination, non de la raison ; la morale ne consiste pas à être heureux mais à se rendre digne du bonheur."], ["Pascal", "l'homme se divertit pour ne pas penser à sa condition misérable ; le vrai bonheur n'est pas dans ce monde."]],
  distinctions: "Bonheur / plaisir ; bonheur / joie ; désir / besoin.",
  sujetsEx: ["Le bonheur est-il affaire de chance ?", "Faut-il chercher à être heureux ?", "Le bonheur est-il un droit ?"],
  quiz: [["L'ataraxie est…", ["l'absence de trouble de l'âme", "la recherche du plaisir maximal", "le renoncement à tout désir", "une vertu politique"], "C'est l'idéal d'Épicure."], ["Pour Kant, le bonheur est…", ["un idéal de l'imagination", "un concept clair de la raison", "le but de la morale", "une illusion à combattre"], "On ne peut pas savoir avec certitude ce qui nous rendra heureux."], ["Selon Épictète, il faut distinguer…", ["ce qui dépend de nous et ce qui n'en dépend pas", "le corps et l'esprit", "les plaisirs et les douleurs", "les riches et les pauvres"], "Nos jugements dépendent de nous, pas les événements."], ["Pour Aristote, le bonheur est…", ["la fin suprême, recherchée pour elle-même", "un simple plaisir", "impossible à atteindre", "réservé aux riches"], "Tout le reste est recherché en vue du bonheur."]],
  exos: [["Le bonheur dépend-il de nous ?", "Le bonheur est-il le fruit de nos choix et de notre sagesse, ou dépend-il de circonstances que nous ne maîtrisons pas ?", plan("Le bonheur semble dépendre de la chance (santé, naissance, rencontres) : l'étymologie de « bon heur » renvoie à la bonne fortune.", "Mais la sagesse nous rend maîtres de notre bonheur : tri des désirs (Épicure), maîtrise de nos jugements (stoïciens).", "Le bonheur est un équilibre : il demande des conditions extérieures (Aristote) et un travail sur soi.")], ["Faut-il satisfaire tous ses désirs pour être heureux ?", "Le bonheur passe-t-il par la satisfaction de tous nos désirs, ou par leur maîtrise ?", plan("Le désir non satisfait est source de frustration : satisfaire ses désirs semble mener au bonheur (Calliclès dans le Gorgias).", "Mais le désir est sans fin : chaque satisfaction en fait naître un autre (le tonneau percé) ; il faut trier ses désirs (Épicure).", "Le bonheur est peut-être dans le désir lui-même et dans son orientation, plutôt que dans sa satisfaction totale.")]] }),
notion({ id: "conscience", nom: "La conscience",
  def: "La conscience est la <b>connaissance que l'esprit a de lui-même</b> et du monde. On distingue la <b>conscience spontanée</b> (je perçois) et la <b>conscience réfléchie</b> (je sais que je perçois). La conscience morale juge le bien et le mal.",
  problemes: ["La conscience me donne-t-elle une connaissance certaine de moi-même ?", "Suis-je ce que j'ai conscience d'être ?", "La conscience fait-elle la dignité de l'homme ?", "Peut-on être conscient de tout ce qu'on fait ?"],
  positions: [["Descartes", "« Je pense, donc je suis » : la conscience de soi est la première certitude, que le doute ne peut atteindre."], ["Pascal", "l'homme n'est qu'un roseau, mais un roseau pensant : sa conscience fait sa grandeur et sa misère."], ["Locke", "l'identité personnelle repose sur la conscience et la mémoire."], ["Husserl", "toute conscience est conscience de quelque chose (intentionnalité)."], ["Freud", "le moi n'est pas maître dans sa propre maison : une grande partie de notre vie psychique est inconsciente."]],
  distinctions: "Conscience spontanée / réfléchie ; conscience psychologique / morale ; sujet / objet.",
  sujetsEx: ["La conscience de soi est-elle une connaissance de soi ?", "Suis-je ce que j'ai conscience d'être ?"],
  quiz: [["« Je pense, donc je suis » est de…", ["Descartes", "Pascal", "Kant", "Sartre"], "C'est le cogito, première vérité indubitable."], ["« Toute conscience est conscience de quelque chose » définit…", ["l'intentionnalité (Husserl)", "l'inconscient (Freud)", "le cogito (Descartes)", "le roseau pensant (Pascal)"], "La conscience est toujours tournée vers un objet."], ["Pour Pascal, l'homme est…", ["un roseau pensant", "un animal politique", "une chose qui pense seulement", "un loup pour l'homme"], "Sa grandeur vient de ce qu'il sait qu'il est misérable."], ["Pour Locke, l'identité personnelle repose sur…", ["la conscience et la mémoire", "le corps", "le nom", "la société"], "Je suis la même personne tant que je me souviens de mes actes."]],
  exos: [["La conscience de soi est-elle une connaissance de soi ?", "Avoir conscience de soi suffit-il à se connaître vraiment ?", plan("La conscience de soi est une certitude immédiate : je sais que je pense et que j'existe (Descartes).", "Mais savoir que j'existe n'est pas savoir qui je suis : l'inconscient (Freud), les illusions et la mauvaise foi limitent la connaissance de soi.", "La connaissance de soi est une tâche : elle passe par les autres, les actes et le temps.")], ["Suis-je ce que j'ai conscience d'être ?", "Mon identité se réduit-elle à l'image que j'ai de moi-même ?", plan("Oui en un sens : la conscience et la mémoire font mon identité personnelle (Locke).", "Non : une part de moi m'échappe (inconscient, habitudes, regard des autres).", "Je suis aussi ce que je fais : l'existence précède l'essence (Sartre), je me construis par mes actes.")]] }),
notion({ id: "devoir", nom: "Le devoir",
  def: "Le devoir est une <b>obligation</b> : ce qu'on doit faire, que ce soit imposé par la morale, la loi ou la société. Il se distingue de la <b>contrainte</b>, qui force sans laisser de choix.",
  problemes: ["Faire son devoir, est-ce renoncer à sa liberté ?", "D'où vient le devoir : de la raison, de la société, de Dieu ?", "Peut-on avoir le devoir de désobéir ?", "Suffit-il de faire son devoir pour être moral ?"],
  positions: [["Kant", "le devoir est commandé par la raison sous forme d'impératif catégorique : « Agis uniquement d'après la maxime qui fait que tu peux vouloir en même temps qu'elle devienne une loi universelle ». Agir par devoir, et non seulement conformément au devoir."], ["Durkheim", "la morale et le devoir viennent de la société, qui s'impose à l'individu."], ["Rousseau", "l'obéissance à la loi qu'on s'est prescrite est liberté."], ["Antigone (Sophocle)", "désobéit à la loi de Créon au nom d'un devoir supérieur (enterrer son frère)."], ["Thoreau", "la désobéissance civile est un devoir face à une loi injuste."]],
  distinctions: "Obligation / contrainte ; agir par devoir / conformément au devoir ; légal / légitime.",
  sujetsEx: ["Faire son devoir, est-ce renoncer à sa liberté ?", "Peut-on avoir le devoir de désobéir ?"],
  quiz: [["L'impératif catégorique est une idée de…", ["Kant", "Hume", "Durkheim", "Mill"], "Un commandement inconditionnel de la raison."], ["Un commerçant honnête par intérêt agit, selon Kant,…", ["conformément au devoir mais pas par devoir", "par devoir", "contre le devoir", "par vertu"], "Seule l'action par devoir a une valeur morale."], ["La différence entre obligation et contrainte :", ["l'obligation suppose qu'on puisse désobéir", "la contrainte est morale", "l'obligation est physique", "il n'y en a aucune"], "On est obligé, mais on peut refuser ; on est contraint par la force."], ["Antigone illustre…", ["le conflit entre loi de la cité et devoir moral", "l'obéissance aveugle", "le contrat social", "le bonheur"], "Elle enterre son frère malgré l'interdiction de Créon."]],
  exos: [["Faire son devoir, est-ce renoncer à sa liberté ?", "Le devoir, qui m'impose des obligations, limite-t-il ma liberté ou en est-il la condition ?", plan("Le devoir semble s'opposer à la liberté : il m'impose des règles venues de la société ou de l'autorité.", "Mais l'obligation n'est pas une contrainte : je peux désobéir, et c'est en choisissant de faire mon devoir que j'exerce ma liberté.", "Chez Kant, la raison se donne à elle-même la loi morale : obéir au devoir, c'est être autonome, donc libre.")], ["Peut-on avoir le devoir de désobéir ?", "L'obéissance aux lois est-elle toujours un devoir, ou la morale peut-elle exiger de désobéir ?", plan("Le devoir du citoyen est d'obéir aux lois : sans cela, il n'y a plus de société (Socrate refuse de s'évader).", "Mais une loi peut être injuste : la conscience morale peut imposer de désobéir (Antigone, Thoreau, la Résistance).", "La désobéissance doit rester exceptionnelle, publique et non violente pour être légitime (désobéissance civile)."), 3]] }),
notion({ id: "etat", nom: "L'État",
  def: "L'État est l'<b>autorité politique souveraine</b> qui s'exerce sur un territoire et une population, à travers des institutions (gouvernement, administration, justice, armée). Selon Max Weber, il détient le <b>monopole de la violence physique légitime</b>.",
  problemes: ["L'État est-il nécessaire ou peut-on s'en passer ?", "L'État garantit-il ou menace-t-il la liberté ?", "D'où vient la légitimité du pouvoir de l'État ?", "L'État doit-il rendre les hommes heureux ?"],
  positions: [["Hobbes", "à l'état de nature, « l'homme est un loup pour l'homme » ; les hommes passent un contrat et confient le pouvoir à un souverain absolu (Léviathan) pour garantir leur sécurité."], ["Locke", "l'État doit protéger les droits naturels (vie, liberté, propriété) ; si le pouvoir les viole, le peuple peut résister."], ["Rousseau", "le contrat social fonde un État où le peuple est souverain et obéit à la volonté générale."], ["Marx", "l'État est un instrument de domination de la classe dominante ; il doit disparaître."], ["Weber", "l'État revendique le monopole de la violence physique légitime ; trois types de légitimité : traditionnelle, charismatique, légale-rationnelle."]],
  distinctions: "Légal / légitime ; pouvoir / autorité ; État / société civile ; public / privé.",
  sujetsEx: ["L'État est-il l'ennemi de la liberté ?", "Peut-on se passer de l'État ?"],
  quiz: [["« L'homme est un loup pour l'homme » est associé à…", ["Hobbes", "Rousseau", "Locke", "Aristote"], "Il décrit ainsi l'état de nature."], ["Le monopole de la violence physique légitime définit l'État chez…", ["Weber", "Marx", "Kant", "Platon"], "C'est la définition sociologique de l'État."], ["Pour Rousseau, le souverain est…", ["le peuple", "le roi", "le gouvernement", "l'Église"], "Le peuple obéit à la volonté générale qu'il exprime."], ["Pour Marx, l'État…", ["sert la classe dominante", "est neutre", "est éternel", "protège les plus faibles"], "Il devrait dépérir dans une société sans classes."]],
  exos: [["L'État est-il l'ennemi de la liberté ?", "L'État, qui impose des lois et détient la force, limite-t-il nécessairement la liberté, ou en est-il la condition ?", plan("L'État contraint : lois, impôts, police ; il peut devenir tyrannique (critique anarchiste, Marx).", "Mais sans État, la liberté naturelle est menacée par la violence de tous (Hobbes) : l'État garantit la sécurité et les droits (Locke).", "Un État légitime, fondé sur le contrat et la volonté générale, rend les citoyens libres (Rousseau) : tout dépend de la forme de l'État.")], ["Peut-on se passer de l'État ?", "Une société peut-elle vivre sans autorité politique centrale ?", plan("L'État semble nécessaire pour garantir la paix et la justice (Hobbes, Weber).", "Des penseurs anarchistes et Marx imaginent une société sans État, et des sociétés traditionnelles ont vécu sans État centralisé.", "On peut limiter l'État et développer d'autres formes d'organisation, mais la coordination de grandes sociétés exige des institutions communes.")]] }),
notion({ id: "inconscient", nom: "L'inconscient",
  def: "L'inconscient désigne ce qui, dans le psychisme, <b>échappe à la conscience</b>. Avec Freud, c'est une instance psychique qui contient des désirs refoulés et influence nos pensées et nos actes.",
  problemes: ["L'hypothèse de l'inconscient est-elle légitime ?", "Si je suis déterminé par mon inconscient, suis-je encore libre et responsable ?", "Peut-on connaître son inconscient ?"],
  positions: [["Leibniz", "les « petites perceptions » : nous percevons sans nous en apercevoir (le bruit de chaque vague dans le grondement de la mer)."], ["Freud", "le moi n'est pas maître dans sa propre maison ; l'inconscient se manifeste dans les rêves, les lapsus, les actes manqués ; trois instances : ça, moi, surmoi."], ["Alain", "critique : l'inconscient est une façon de se dédoubler et de se décharger de sa responsabilité."], ["Sartre", "refuse l'inconscient au profit de la mauvaise foi : on se ment à soi-même pour fuir sa liberté."]],
  distinctions: "Inconscient / non-conscient ; refoulement ; responsabilité / culpabilité.",
  sujetsEx: ["L'inconscient est-il une excuse ?", "Peut-on se connaître soi-même ?"],
  quiz: [["Pour Freud, les rêves sont…", ["la voie royale vers l'inconscient", "des messages divins", "sans signification", "des souvenirs exacts"], "Ils réalisent de façon déguisée des désirs refoulés."], ["Les trois instances freudiennes sont…", ["le ça, le moi et le surmoi", "l'âme, le corps et l'esprit", "la raison, la volonté et le désir", "le conscient, le réel et l'imaginaire"], "C'est la deuxième topique."], ["Sartre oppose à l'inconscient…", ["la mauvaise foi", "le cogito", "la volonté générale", "la catharsis"], "On se ment à soi-même pour fuir sa liberté."], ["Les « petites perceptions » sont une idée de…", ["Leibniz", "Descartes", "Freud", "Kant"], "Nous percevons sans en avoir conscience."]],
  exos: [["L'inconscient est-il une excuse ?", "Si une partie de mes actes vient de l'inconscient, cela me dispense-t-il d'en répondre ?", plan("L'inconscient semble diminuer la responsabilité : je ne choisis pas mes désirs refoulés (Freud).", "Mais invoquer l'inconscient peut être une manière de fuir sa liberté (Sartre : mauvaise foi ; Alain).", "Connaître son inconscient (par l'analyse) permet au contraire de devenir plus responsable de soi.")], ["Peut-on se connaître soi-même ?", "La connaissance de soi est-elle possible si une partie de notre psychisme nous échappe ?", plan("La conscience semble nous donner un accès direct à nous-mêmes (Descartes).", "Mais l'inconscient, les illusions et l'amour-propre font obstacle à cette connaissance.", "On peut se connaître indirectement : par ses actes, le regard des autres, le travail sur soi.")]] }),
notion({ id: "justice", nom: "La justice",
  def: "La justice désigne à la fois une <b>vertu</b> (être juste), un <b>idéal</b> (ce qui est juste) et une <b>institution</b> (les tribunaux). Elle repose sur deux idées : l'<b>égalité</b> et le respect du <b>droit</b>.",
  problemes: ["Le juste se réduit-il au légal ?", "La justice consiste-t-elle à traiter tout le monde de la même façon ?", "Peut-on se faire justice soi-même ?", "La justice est-elle une affaire de force ?"],
  positions: [["Platon", "la justice est l'harmonie de l'âme et de la cité, chacun à sa place ; contre Calliclès, pour qui le juste est la loi du plus fort."], ["Aristote", "distingue la justice commutative (égalité arithmétique dans les échanges) et la justice distributive (égalité proportionnelle au mérite) ; l'équité corrige la loi trop générale."], ["Pascal", "« ne pouvant faire que ce qui est juste fût fort, on a fait que ce qui est fort fût juste »."], ["Rawls", "une société juste se définit sous un « voile d'ignorance » ; les inégalités ne sont acceptables que si elles profitent aux plus défavorisés (principe de différence)."]],
  distinctions: "Légal / légitime ; égalité / équité ; droit naturel / droit positif.",
  sujetsEx: ["Le juste se réduit-il au légal ?", "L'égalité est-elle toujours juste ?"],
  quiz: [["Le « voile d'ignorance » est une idée de…", ["Rawls", "Platon", "Aristote", "Hobbes"], "On choisit les principes de justice sans connaître sa future place dans la société."], ["L'équité, chez Aristote, permet…", ["de corriger la loi trop générale dans un cas particulier", "d'appliquer la loi à la lettre", "de punir plus sévèrement", "de supprimer les lois"], "Le juge adapte la loi à la situation."], ["Le droit positif désigne…", ["l'ensemble des lois en vigueur dans une société", "les droits naturels", "les droits de l'homme", "la morale"], "Il s'oppose au droit naturel."], ["Justice distributive selon Aristote :", ["égalité proportionnelle au mérite", "égalité stricte pour tous", "loi du plus fort", "tirage au sort"], "On donne à chacun selon sa valeur ou sa contribution."]],
  exos: [["Le juste se réduit-il au légal ?", "Suffit-il de respecter la loi pour être juste, ou la justice dépasse-t-elle les lois ?", plan("La loi est la référence commune du juste : sans elle, chacun jugerait selon ses intérêts.", "Mais des lois peuvent être injustes (lois racistes, ségrégation) : il existe une idée de justice au-delà du droit positif (droit naturel, droits de l'homme).", "La justice est un idéal qui guide la critique et l'amélioration des lois.")], ["L'égalité est-elle toujours juste ?", "Traiter tout le monde de la même façon est-ce la justice, ou faut-il parfois traiter différemment pour être juste ?", plan("L'égalité devant la loi est le fondement de la justice : mêmes droits pour tous.", "Mais traiter également des situations inégales peut être injuste : la justice distributive tient compte des mérites et des besoins (Aristote, équité).", "Rawls : des inégalités sont justes si elles profitent aux plus défavorisés."), 3]] }),
notion({ id: "langage", nom: "Le langage",
  def: "Le langage est la <b>faculté de communiquer</b> au moyen de signes. Les langues humaines sont des systèmes de signes arbitraires et conventionnels. Le langage humain se distingue de la communication animale par sa capacité à créer des énoncés nouveaux et à exprimer des idées abstraites.",
  problemes: ["Le langage est-il seulement un outil de communication ?", "Pensons-nous sans les mots ?", "Les mots trahissent-ils la pensée ?", "Parler, est-ce agir ?"],
  positions: [["Descartes", "le langage est le signe de la pensée : les animaux, même capables de proférer des sons, ne parlent pas."], ["Benveniste", "les abeilles communiquent par un code fixe, mais n'ont pas de langage : leur message ne peut pas être reformulé ni porter sur un autre message."], ["Hegel", "c'est dans les mots que nous pensons ; l'ineffable n'est que la pensée obscure."], ["Bergson", "les mots, généraux, ne saisissent pas l'individualité de nos états intérieurs."], ["Austin", "certains énoncés sont performatifs : dire « je le promets », c'est faire une promesse."]],
  distinctions: "Langage / langue / parole ; signe / signal ; signifiant / signifié.",
  sujetsEx: ["Peut-on penser sans les mots ?", "Le langage trahit-il la pensée ?"],
  quiz: [["Selon Benveniste, la communication des abeilles…", ["n'est pas un langage au sens humain", "est un langage complet", "est plus riche que le nôtre", "n'existe pas"], "Elle ne permet ni dialogue ni reformulation."], ["« Je déclare la séance ouverte » est un énoncé…", ["performatif", "descriptif", "faux", "interrogatif"], "Austin : dire, c'est faire."], ["Pour Hegel, la pensée…", ["se forme dans les mots", "existe avant les mots", "est ineffable", "n'a pas besoin de langage"], "L'ineffable n'est qu'une pensée encore confuse."], ["Pour Bergson, les mots…", ["ne saisissent pas l'individualité de nos états intérieurs", "expriment parfaitement nos sentiments", "sont inutiles", "créent la réalité"], "Ils sont généraux et figés."]],
  exos: [["Peut-on penser sans les mots ?", "La pensée existe-t-elle avant le langage, ou se forme-t-elle en lui ?", plan("On a l'impression de chercher ses mots : la pensée précéderait le langage (intuitions, images, émotions).", "Mais une pensée claire et précise se forme dans les mots (Hegel) ; sans langage, la pensée reste confuse.", "Pensée et langage se construisent ensemble ; certaines expériences (art, émotions) débordent pourtant les mots (Bergson).")], ["Le langage trahit-il la pensée ?", "Les mots expriment-ils fidèlement ce que nous pensons, ou déforment-ils notre pensée ?", plan("Les mots sont généraux et ne disent pas la singularité de ce que je ressens (Bergson).", "Mais sans les mots, la pensée n'existe pas vraiment : c'est en les formulant que nous savons ce que nous pensons (Hegel).", "La trahison vient plutôt de l'usage : le travail de l'écrivain ou du poète montre que le langage peut dire le singulier.")]] }),
notion({ id: "liberte", nom: "La liberté",
  def: "Être libre, c'est d'abord <b>ne pas subir de contrainte</b> (liberté d'action). Mais c'est aussi pouvoir <b>choisir</b> (libre arbitre) et se donner à soi-même sa propre loi (<b>autonomie</b>). La liberté politique est garantie par les droits.",
  problemes: ["Être libre, est-ce faire ce que l'on veut ?", "Sommes-nous libres ou déterminés ?", "La loi limite-t-elle ou garantit-elle la liberté ?", "La liberté est-elle une illusion ?"],
  positions: [["Descartes", "le libre arbitre est infini : la volonté peut toujours choisir, même contre l'évidence."], ["Spinoza", "les hommes se croient libres parce qu'ils sont conscients de leurs désirs mais ignorent les causes qui les déterminent ; la liberté consiste à comprendre la nécessité."], ["Rousseau", "« l'obéissance à la loi qu'on s'est prescrite est liberté »."], ["Kant", "la liberté est autonomie : la volonté se donne à elle-même la loi morale."], ["Sartre", "« l'homme est condamné à être libre » : il est responsable de ce qu'il fait de lui-même."]],
  distinctions: "Libre arbitre / déterminisme ; autonomie / hétéronomie ; liberté / licence.",
  sujetsEx: ["Être libre, est-ce faire ce que l'on veut ?", "La liberté est-elle une illusion ?"],
  quiz: [["« L'homme est condamné à être libre » est de…", ["Sartre", "Spinoza", "Rousseau", "Kant"], "Il ne peut pas échapper à ses choix."], ["Pour Spinoza, l'illusion de la liberté vient de ce que…", ["nous ignorons les causes qui nous déterminent", "nous n'avons pas de désirs", "nous sommes trop raisonnables", "les lois sont injustes"], "Comme la pierre qui croirait tomber librement."], ["L'autonomie, chez Kant, c'est…", ["se donner à soi-même sa loi", "faire ce qu'on veut", "obéir à ses désirs", "vivre seul"], "Elle s'oppose à l'hétéronomie."], ["« L'obéissance à la loi qu'on s'est prescrite est liberté » est de…", ["Rousseau", "Hobbes", "Descartes", "Marx"], "Du contrat social."]],
  exos: [["Être libre, est-ce faire ce que l'on veut ?", "La liberté consiste-t-elle à satisfaire tous ses désirs, ou suppose-t-elle une maîtrise de soi ?", plan("Spontanément, être libre c'est ne pas être empêché de faire ce qu'on veut.", "Mais suivre ses désirs, c'est souvent être esclave de ses passions et ignorer ce qui nous détermine (Spinoza).", "La vraie liberté est autonomie : se donner sa propre loi par la raison (Kant, Rousseau).")], ["Sommes-nous libres ?", "L'homme est-il l'auteur de ses choix, ou est-il déterminé par des causes qui lui échappent ?", plan("Nous faisons l'expérience du choix : la volonté peut toujours dire oui ou non (Descartes).", "Mais nous sommes déterminés par notre corps, notre inconscient, notre société (Spinoza, sciences humaines).", "La liberté n'est pas donnée mais conquise : comprendre ses déterminations pour agir sur elles ; et nous restons responsables de nos actes (Sartre)."), 3]] }),
notion({ id: "nature", nom: "La nature",
  def: "La nature désigne l'ensemble des choses qui existent <b>sans intervention humaine</b> et obéissent à des lois. On parle aussi de la nature d'une chose (son essence) et de la <b>nature humaine</b>. Elle s'oppose à la culture et à l'art.",
  problemes: ["Existe-t-il une nature humaine ?", "L'homme doit-il dominer la nature ou la respecter ?", "La nature peut-elle servir de modèle moral ?", "Ce qui est naturel est-il bon ?"],
  positions: [["Aristote", "la nature est principe de mouvement ; « la nature ne fait rien en vain »."], ["Descartes", "la science doit nous rendre « comme maîtres et possesseurs de la nature »."], ["Rousseau", "l'homme naturel est bon, c'est la société qui le corrompt ; sa nature est perfectible."], ["Sartre", "il n'y a pas de nature humaine : l'existence précède l'essence."], ["Hans Jonas", "le principe responsabilité : agir de façon que les effets de notre action soient compatibles avec la permanence d'une vie authentiquement humaine sur terre."]],
  distinctions: "Nature / culture ; naturel / artificiel ; inné / acquis.",
  sujetsEx: ["L'homme doit-il dominer la nature ?", "Existe-t-il une nature humaine ?"],
  quiz: [["« Maîtres et possesseurs de la nature » est une formule de…", ["Descartes", "Rousseau", "Jonas", "Aristote"], "Discours de la méthode, sixième partie."], ["Le principe responsabilité est de…", ["Hans Jonas", "Kant", "Sartre", "Platon"], "Il pense notre responsabilité envers les générations futures."], ["« L'existence précède l'essence » signifie que…", ["l'homme se définit par ses actes, sans nature fixée d'avance", "la nature humaine est fixe", "l'homme est naturellement bon", "Dieu a créé l'homme"], "C'est l'existentialisme de Sartre."], ["Pour Rousseau, l'homme est…", ["perfectible", "naturellement méchant", "une machine", "déterminé par ses gènes"], "Il peut se transformer, pour le meilleur et pour le pire."]],
  exos: [["L'homme doit-il dominer la nature ?", "La maîtrise de la nature est-elle un progrès légitime ou une menace pour l'homme lui-même ?", plan("Dominer la nature permet de se protéger et de vivre mieux (Descartes : science et technique).", "Mais cette domination détruit les conditions de la vie (crise écologique) : il faut une éthique de la responsabilité (Jonas).", "L'enjeu est de maîtriser notre propre maîtrise : l'homme fait partie de la nature.")], ["Existe-t-il une nature humaine ?", "Y a-t-il une essence commune à tous les hommes, ou l'homme se définit-il par ce qu'il fait de lui-même ?", plan("Les hommes partagent des besoins, la raison, le langage : une nature humaine semble exister.", "Mais la diversité des cultures et l'histoire montrent que l'homme se construit (Rousseau : perfectibilité ; Sartre).", "La nature humaine est peut-être justement de ne pas avoir de nature figée.")]] }),
notion({ id: "raison", nom: "La raison",
  def: "La raison est la <b>faculté de penser de façon ordonnée</b> : juger, démontrer, distinguer le vrai du faux et le bien du mal. Elle est aussi le principe d'explication des choses (« la raison d'être »).",
  problemes: ["La raison peut-elle tout connaître ?", "Faut-il opposer la raison et les passions ?", "Peut-on tout démontrer ?", "La raison est-elle la même chez tous les hommes ?"],
  positions: [["Descartes", "« le bon sens est la chose du monde la mieux partagée » : tous ont la raison, il faut bien l'appliquer (méthode)."], ["Pascal", "« le cœur a ses raisons que la raison ne connaît point » ; les premiers principes sont sentis, pas démontrés."], ["Hume", "« la raison est et ne doit être que l'esclave des passions »."], ["Kant", "la raison a des limites : elle ne peut pas connaître ce qui dépasse l'expérience (Dieu, l'âme), elle peut seulement le penser."], ["Leibniz", "principe de raison suffisante : rien n'arrive sans raison."]],
  distinctions: "Démontrer / croire ; raison / passion ; rationnel / raisonnable.",
  sujetsEx: ["La raison peut-elle tout expliquer ?", "Faut-il se méfier des passions ?"],
  quiz: [["« Le cœur a ses raisons que la raison ne connaît point » est de…", ["Pascal", "Descartes", "Kant", "Hume"], "Pensées."], ["Pour Hume, la raison est…", ["l'esclave des passions", "le maître des passions", "inutile", "divine"], "Elle sert à trouver les moyens de satisfaire nos passions."], ["Le principe de raison suffisante est de…", ["Leibniz", "Spinoza", "Aristote", "Hegel"], "Rien n'arrive sans cause ou raison."], ["Pour Kant, la raison…", ["ne peut pas connaître ce qui dépasse l'expérience", "peut tout connaître", "est inférieure aux sens", "est réservée aux savants"], "Critique de la raison pure."]],
  exos: [["La raison peut-elle tout expliquer ?", "La raison a-t-elle des limites, ou tout est-il en droit compréhensible ?", plan("La raison cherche la cause de toute chose (Leibniz) et la science étend sans cesse ce qu'elle explique.", "Mais elle a des limites : les premiers principes ne se démontrent pas (Pascal), ce qui dépasse l'expérience n'est pas connaissable (Kant).", "Reconnaître ses limites est encore un acte de la raison, qui distingue savoir et croire.")], ["Faut-il opposer la raison et les passions ?", "La raison doit-elle combattre les passions, ou ont-elles besoin l'une de l'autre ?", plan("Les passions troublent le jugement : la sagesse consiste à les maîtriser par la raison (stoïciens, Descartes).", "Mais sans passions, rien ne pousse à agir : la raison ne fait que trouver des moyens (Hume) ; « rien de grand ne s'est fait sans passion » (Hegel).", "Il faut éduquer les passions plutôt que les supprimer.")]] }),
notion({ id: "religion", nom: "La religion",
  def: "La religion est un ensemble de <b>croyances</b> et de <b>pratiques</b> (rites) relatives au sacré, qui <b>relient</b> les membres d'une communauté. Elle répond aux questions de l'origine, du sens de la vie et de la mort.",
  problemes: ["La religion est-elle une affaire privée ou sociale ?", "La foi s'oppose-t-elle à la raison ?", "La religion est-elle une illusion ?", "Peut-on se passer de religion ?"],
  positions: [["Durkheim", "la religion sépare le sacré du profane ; elle est un ciment social, et le sacré exprime la société elle-même."], ["Marx", "la religion est « l'opium du peuple » : elle console des souffrances réelles et détourne de leur transformation."], ["Freud", "la religion est une illusion, née du désir de protection d'un père tout-puissant."], ["Pascal", "le pari : on a tout à gagner à croire en Dieu ; Dieu est sensible au cœur."], ["Kant", "on ne peut pas prouver l'existence de Dieu, mais on peut l'admettre comme postulat de la raison pratique."]],
  distinctions: "Croire / savoir ; foi / raison ; sacré / profane.",
  sujetsEx: ["La religion n'est-elle qu'une affaire privée ?", "Peut-on prouver l'existence de Dieu ?"],
  quiz: [["« L'opium du peuple » désigne la religion chez…", ["Marx", "Freud", "Durkheim", "Nietzsche"], "Elle console mais empêche de changer le monde."], ["Pour Durkheim, la religion distingue…", ["le sacré et le profane", "le bien et le mal", "le corps et l'âme", "la foi et la raison"], "Les Formes élémentaires de la vie religieuse."], ["Le pari est un argument de…", ["Pascal", "Descartes", "Kant", "Spinoza"], "Si Dieu existe, on gagne tout ; sinon on ne perd rien."], ["Pour Freud, la religion est…", ["une illusion née du désir", "une vérité scientifique", "un ciment social", "une invention des prêtres"], "L'Avenir d'une illusion."]],
  exos: [["La religion n'est-elle qu'une affaire privée ?", "La religion relève-t-elle seulement de la conscience individuelle, ou a-t-elle une dimension collective et politique ?", plan("La foi est intime : la laïcité garantit la liberté de conscience et sépare religion et État.", "Mais la religion est collective : rites, communauté, ciment social (Durkheim) ; elle a aussi des effets politiques (Marx).", "La laïcité ne privatise pas la religion : elle organise sa place dans l'espace commun.")], ["La foi s'oppose-t-elle à la raison ?", "Croire, est-ce renoncer à penser, ou foi et raison peuvent-elles s'accorder ?", plan("La foi croit sans preuve, là où la raison exige des démonstrations : elles semblent opposées.", "Mais la raison a des limites, et la foi répond à des questions qu'elle laisse ouvertes (Pascal, Kant).", "Foi et raison peuvent coexister si chacune reste dans son domaine.")]] }),
notion({ id: "science", nom: "La science",
  def: "La science est une <b>connaissance rationnelle, méthodique et vérifiable</b> du réel. Elle cherche des lois générales par la démonstration (mathématiques) ou par l'expérimentation (sciences de la nature).",
  problemes: ["La science peut-elle atteindre la vérité ?", "Qu'est-ce qui distingue une théorie scientifique d'une croyance ?", "La science est-elle neutre moralement ?", "Les sciences humaines sont-elles des sciences comme les autres ?"],
  positions: [["Bachelard", "l'esprit scientifique se forme contre les opinions et les obstacles épistémologiques ; « l'opinion pense mal »."], ["Popper", "une théorie est scientifique si elle est réfutable (falsifiable) : elle peut être mise à l'épreuve et démentie par l'expérience."], ["Claude Bernard", "la méthode expérimentale : observation, hypothèse, expérimentation."], ["Kuhn", "la science progresse par révolutions scientifiques qui changent de paradigme."], ["Auguste Comte", "les sciences passent de l'état théologique à l'état métaphysique puis positif."]],
  distinctions: "Démontrer / expérimenter ; hypothèse / loi / théorie ; expliquer / comprendre.",
  sujetsEx: ["La science peut-elle tout expliquer ?", "Une théorie scientifique peut-elle être vraie ?"],
  quiz: [["Le critère de réfutabilité est dû à…", ["Popper", "Bachelard", "Kuhn", "Comte"], "Une théorie scientifique doit pouvoir être contredite par l'expérience."], ["Pour Bachelard, l'opinion…", ["pense mal", "est la base de la science", "est toujours vraie", "est inutile à combattre"], "La science se construit contre elle."], ["La notion de « révolution scientifique » et de paradigme est de…", ["Kuhn", "Popper", "Descartes", "Claude Bernard"], "La Structure des révolutions scientifiques."], ["L'astrologie n'est pas scientifique selon Popper car…", ["elle n'est pas réfutable", "elle est trop ancienne", "elle parle des astres", "elle est fausse"], "Ses prédictions sont formulées de façon à ne jamais être démenties."]],
  exos: [["Une théorie scientifique peut-elle être vraie ?", "Si les théories scientifiques sont révisées au cours de l'histoire, peuvent-elles prétendre à la vérité ?", plan("La science vise le vrai par des méthodes rigoureuses (démonstration, expérimentation).", "Mais l'histoire des sciences montre que les théories sont dépassées (Kuhn) ; une théorie n'est jamais vérifiée définitivement, seulement non encore réfutée (Popper).", "La vérité scientifique est une approximation progressive : la science corrige ses erreurs.")], ["La science peut-elle tout expliquer ?", "Existe-t-il des domaines qui échappent à la connaissance scientifique ?", plan("La science étend sans cesse ce qu'elle explique, et ses méthodes s'appliquent à de nombreux domaines.", "Mais elle ne dit pas ce qui doit être (valeurs, sens de la vie) et le vécu singulier lui échappe en partie.", "La science explique le « comment », d'autres approches (philosophie, art, morale) interrogent le « pourquoi »."), 3]] }),
notion({ id: "technique", nom: "La technique",
  def: "La technique est l'ensemble des <b>procédés et des outils</b> par lesquels l'homme transforme la nature pour satisfaire ses besoins. Elle prolonge et dépasse les capacités du corps humain.",
  problemes: ["La technique libère-t-elle l'homme ou l'asservit-elle ?", "La technique est-elle neutre ?", "Tout ce qui est techniquement possible est-il souhaitable ?", "La technique fait-elle de l'homme un être à part ?"],
  positions: [["Platon (mythe de Prométhée)", "l'homme, nu et désarmé, reçoit le feu et les arts pour survivre."], ["Aristote", "la main est l'outil des outils : l'homme est intelligent et a donc des mains."], ["Bergson", "l'homme est homo faber avant d'être homo sapiens : l'intelligence est la faculté de fabriquer des outils."], ["Descartes", "la technique, guidée par la science, doit nous rendre maîtres et possesseurs de la nature."], ["Heidegger", "la technique moderne arraisonne la nature, considérée comme un simple stock de ressources."], ["Hans Jonas", "la puissance technique impose une nouvelle éthique de la responsabilité."]],
  distinctions: "Technique / science ; outil / machine ; moyen / fin.",
  sujetsEx: ["La technique nous libère-t-elle ?", "Tout ce qui est possible techniquement doit-il être fait ?"],
  quiz: [["Homo faber est une expression associée à…", ["Bergson", "Platon", "Kant", "Heidegger"], "L'homme se définit d'abord par sa capacité à fabriquer."], ["Pour Aristote, la main est…", ["l'outil des outils", "inférieure à l'esprit", "un simple organe", "un don divin"], "Elle peut devenir tous les outils."], ["L'idée d'arraisonnement de la nature par la technique est de…", ["Heidegger", "Descartes", "Bergson", "Rousseau"], "La nature devient un stock de ressources."], ["Dans le mythe de Prométhée, l'homme reçoit…", ["le feu et les arts", "la raison pure", "la justice seulement", "l'immortalité"], "Il compense ainsi sa faiblesse naturelle."]],
  exos: [["La technique nous libère-t-elle ?", "Le progrès technique émancipe-t-il l'homme ou crée-t-il de nouvelles dépendances ?", plan("La technique libère des contraintes naturelles : travail, maladie, distances (Descartes, Prométhée).", "Mais elle crée de nouvelles servitudes : dépendance aux machines, aliénation du travail, menace écologique (Heidegger, Jonas).", "La technique est un moyen : tout dépend des fins que nous lui donnons et de notre capacité à la maîtriser.")], ["Tout ce qui est techniquement possible est-il souhaitable ?", "La possibilité technique justifie-t-elle à elle seule qu'on réalise une chose ?", plan("Le progrès technique a souvent apporté des bienfaits imprévus : limiter la recherche serait freiner le progrès.", "Mais certaines possibilités menacent l'humanité ou la dignité (armes, manipulations génétiques) : il faut une éthique (Jonas).", "Le souhaitable se décide collectivement, par la réflexion morale et politique.")]] }),
notion({ id: "temps", nom: "Le temps",
  def: "Le temps est la <b>succession</b> des événements (passé, présent, futur) et leur <b>durée</b>. On distingue le temps mesuré (des horloges) et le temps vécu (la durée intérieure).",
  problemes: ["Qu'est-ce que le temps, s'il n'est jamais saisissable ?", "Le temps est-il seulement destructeur ?", "Peut-on échapper au temps ?", "Le temps vécu est-il le même que le temps mesuré ?"],
  positions: [["Saint Augustin", "« Qu'est-ce donc que le temps ? Si personne ne me le demande, je le sais ; si je veux l'expliquer, je ne le sais plus. » Le temps est dans l'âme : mémoire, attention, attente."], ["Bergson", "la durée vécue est qualitative, continue ; le temps des horloges la spatialise et la déforme."], ["Pascal", "nous ne vivons jamais le présent : nous regrettons le passé ou espérons l'avenir."], ["Épicure, Horace", "« Carpe diem » : cueillir le jour présent."]],
  distinctions: "Temps / durée ; instant / éternité ; mémoire / histoire.",
  sujetsEx: ["Le temps n'est-il qu'un obstacle au bonheur ?", "Peut-on vivre au présent ?"],
  quiz: [["« Si personne ne me le demande, je le sais » parle du temps chez…", ["saint Augustin", "Bergson", "Kant", "Heidegger"], "Confessions, livre XI."], ["Pour Bergson, la durée est…", ["vécue, qualitative et continue", "mesurable par les horloges", "une illusion", "un espace"], "Le temps mesuré la spatialise."], ["Pour Pascal, nous ne vivons jamais…", ["le présent", "le passé", "l'avenir", "l'éternité"], "Nous ne pensons au présent que pour disposer de l'avenir."], ["« Carpe diem » invite à…", ["profiter du jour présent", "prévoir l'avenir", "se souvenir du passé", "travailler sans relâche"], "Formule du poète Horace."]],
  exos: [["Peut-on vivre au présent ?", "Est-il possible et souhaitable de ne vivre que dans l'instant ?", plan("Le présent est le seul temps réel ; la sagesse invite à en profiter (carpe diem).", "Mais nous ne vivons jamais le présent (Pascal) : la conscience est toujours tendue vers le passé et l'avenir (Augustin).", "Vivre au présent n'est pas oublier le passé et l'avenir, mais habiter pleinement ce qu'on fait.")], ["Le temps est-il seulement destructeur ?", "Le temps ne fait-il que nous user et nous rapprocher de la mort, ou permet-il aussi de créer et de grandir ?", plan("Le temps use, fait vieillir et mourir : il semble l'ennemi de l'homme.", "Mais il est aussi la condition du progrès, de l'apprentissage, de la mémoire et de l'histoire.", "Pour Bergson, la durée est création continue de nouveauté.")]] }),
notion({ id: "travail", nom: "Le travail",
  def: "Le travail est l'<b>activité par laquelle l'homme transforme la nature</b> pour produire ce dont il a besoin. Étymologiquement associé à la souffrance (tripalium), il est aussi une source de réalisation de soi.",
  problemes: ["Le travail est-il une malédiction ou une libération ?", "Travaille-t-on seulement pour vivre ?", "Le travail rend-il l'homme plus humain ?", "Une société sans travail est-elle souhaitable ?"],
  positions: [["La Genèse", "le travail est une punition : « tu gagneras ton pain à la sueur de ton front »."], ["Hegel", "la dialectique du maître et de l'esclave : par le travail, l'esclave transforme la nature, se forme et se libère."], ["Marx", "le travail est l'essence de l'homme, mais dans le capitalisme il est aliéné : le travailleur est dépossédé du produit et du sens de son travail."], ["Arendt", "distingue le travail (cycle des besoins vitaux), l'œuvre (fabrication d'objets durables) et l'action (vie politique)."], ["Simone Weil", "la condition ouvrière : le travail à la chaîne détruit la pensée et la dignité."]],
  distinctions: "Travail / œuvre / action ; travail / emploi ; aliénation.",
  sujetsEx: ["Le travail est-il une contrainte ?", "Travailler, est-ce seulement gagner sa vie ?"],
  quiz: [["La dialectique du maître et de l'esclave est de…", ["Hegel", "Marx", "Arendt", "Aristote"], "Le travail forme et libère l'esclave."], ["L'aliénation du travail est un concept clé de…", ["Marx", "Kant", "Platon", "Bergson"], "Le travailleur devient étranger à son travail."], ["Arendt distingue…", ["le travail, l'œuvre et l'action", "le travail et le loisir", "le corps et l'esprit", "l'outil et la machine"], "Condition de l'homme moderne."], ["L'étymologie souvent associée à « travail » est…", ["tripalium, un instrument de torture", "labor, la gloire", "opus, le chef-d'œuvre", "ergon, le jeu"], "Elle évoque la souffrance."]],
  exos: [["Le travail est-il une contrainte ?", "Le travail n'est-il qu'une nécessité pénible, ou peut-il être une activité épanouissante ?", plan("Le travail est imposé par les besoins et souvent pénible (Genèse, tripalium).", "Mais il transforme l'homme : il se forme et se libère en travaillant (Hegel, Marx).", "Le caractère contraignant ou libérateur dépend des conditions de travail (aliénation, Simone Weil).")], ["Travailler, est-ce seulement gagner sa vie ?", "Le travail n'a-t-il qu'une fonction économique, ou a-t-il aussi une valeur humaine et sociale ?", plan("On travaille d'abord pour subvenir à ses besoins (Arendt : le travail répond au cycle vital).", "Mais le travail donne une place sociale, une identité, des relations, et permet de produire une œuvre.", "Quand il se réduit au gagne-pain, il devient aliéné : un travail humain doit avoir un sens.")]] }),
notion({ id: "verite", nom: "La vérité",
  def: "La vérité est la qualité d'un énoncé qui est <b>conforme au réel</b> (vérité-correspondance) ou <b>cohérent</b> avec d'autres énoncés (vérité formelle). Elle s'oppose à l'erreur, à l'illusion et au mensonge.",
  problemes: ["La vérité est-elle accessible ou chacun a-t-il sa vérité ?", "Peut-on être certain de quelque chose ?", "Faut-il toujours dire la vérité ?", "La vérité est-elle utile ?"],
  positions: [["Platon", "l'allégorie de la caverne : les hommes prennent des ombres pour la réalité ; la philosophie conduit vers la vérité des Idées."], ["Descartes", "le doute méthodique permet de trouver une première vérité certaine : le cogito ; critère de l'évidence (idées claires et distinctes)."], ["Protagoras", "« l'homme est la mesure de toute chose » : relativisme."], ["Kant", "il ne faut jamais mentir, même à un assassin (contre Benjamin Constant)."], ["Nietzsche", "les vérités sont des illusions dont on a oublié qu'elles le sont."]],
  distinctions: "Vrai / probable / certain ; croire / savoir ; vérité / réalité.",
  sujetsEx: ["La vérité est-elle relative ?", "Faut-il toujours dire la vérité ?"],
  quiz: [["L'allégorie de la caverne est de…", ["Platon", "Aristote", "Descartes", "Nietzsche"], "République, livre VII."], ["« L'homme est la mesure de toute chose » exprime le relativisme de…", ["Protagoras", "Socrate", "Platon", "Kant"], "Chacun aurait sa vérité."], ["Pour Kant, mentir…", ["n'est jamais permis", "est permis pour sauver une vie", "est toujours permis", "est une vertu"], "Débat avec Benjamin Constant."], ["Le doute méthodique conduit Descartes à…", ["une première vérité certaine : le cogito", "douter de tout pour toujours", "rejeter la raison", "la foi seule"], "Le doute est un moyen, pas une fin."]],
  exos: [["La vérité est-elle relative ?", "Chacun a-t-il sa vérité, ou existe-t-il une vérité valable pour tous ?", plan("Les opinions diffèrent selon les cultures et les points de vue : la vérité semble relative (Protagoras).", "Mais dire que tout est relatif, c'est affirmer une vérité absolue : le relativisme se contredit ; la science et la démonstration produisent des vérités universelles.", "Il faut distinguer opinion et vérité : nos connaissances sont parfois partielles, mais la vérité reste l'horizon de la recherche.")], ["Faut-il toujours dire la vérité ?", "Le devoir de vérité est-il absolu, ou peut-on mentir pour de bonnes raisons ?", plan("Le mensonge détruit la confiance et la société ; Kant affirme qu'on ne doit jamais mentir.", "Mais la vérité peut blesser ou mettre en danger : Benjamin Constant défend un mensonge pour protéger un innocent.", "On peut distinguer mentir et taire : le respect d'autrui guide l'usage de la vérité."), 3]] }),
];

/* Les repères du programme, pour l'exercice « Distinguer » */
const REPERES = [
  ["Absolu / relatif", "Est absolu ce qui ne dépend de rien d'autre ; relatif, ce qui dépend d'autre chose ou d'un point de vue.", "« La vérité est-elle relative ? » : une vérité relative dépend du point de vue ; une vérité absolue vaut pour tous."],
  ["Croire / savoir", "Savoir, c'est avoir une connaissance justifiée et vérifiable ; croire, c'est tenir pour vrai sans preuve suffisante.", "Je sais que 2 + 2 = 4 ; je crois qu'il fera beau demain."],
  ["Légal / légitime", "Est légal ce qui est conforme à la loi en vigueur ; légitime, ce qui est juste et fondé en droit ou en raison.", "Une loi raciste était légale mais pas légitime."],
  ["Obligation / contrainte", "L'obligation s'adresse à une liberté qui peut refuser ; la contrainte force physiquement, sans choix.", "Je suis obligé de respecter le code de la route, mais je suis contraint par une menotte."],
  ["Persuader / convaincre", "Convaincre, c'est emporter l'adhésion par des arguments rationnels ; persuader, en jouant sur les émotions.", "Une démonstration convainc ; une publicité persuade."],
  ["Expliquer / comprendre", "Expliquer, c'est rendre compte par des causes (sciences de la nature) ; comprendre, saisir le sens d'une action humaine.", "On explique la chute d'une pierre ; on comprend les raisons d'un révolté."],
  ["En fait / en droit", "En fait renvoie à ce qui est ; en droit, à ce qui doit être ou à ce qui est légitime.", "En fait, des inégalités existent ; en droit, les hommes sont égaux."],
  ["Objectif / subjectif", "Est objectif ce qui vaut indépendamment du sujet ; subjectif, ce qui dépend de la sensibilité ou de l'opinion de chacun.", "La température est objective ; l'impression d'avoir chaud est subjective."],
  ["Universel / général / particulier / singulier", "Universel : vaut pour tous sans exception ; général : vaut pour la plupart ; particulier : vaut pour une partie ; singulier : vaut pour un seul individu.", "« Tous les hommes sont mortels » est universel ; « les Français aiment le pain » est général."],
  ["Origine / fondement", "L'origine est le point de départ historique ; le fondement, ce qui justifie en droit.", "L'origine d'un État peut être une conquête ; son fondement légitime est le consentement des citoyens."],
  ["Nécessaire / contingent", "Est nécessaire ce qui ne peut pas ne pas être ; contingent, ce qui pourrait être autrement.", "La somme des angles d'un triangle est nécessaire ; qu'il pleuve aujourd'hui est contingent."],
  ["Principe / cause / fin", "Le principe est le point de départ d'un raisonnement ou d'une action ; la cause, ce qui produit un effet ; la fin, le but visé.", "La fin de la médecine est la santé ; la cause d'une maladie est un virus."],
  ["Théorie / pratique", "La théorie est une connaissance organisée et désintéressée ; la pratique est l'action concrète.", "Connaître les règles du solfège (théorie) n'est pas jouer du piano (pratique)."],
  ["Transcendant / immanent", "Est transcendant ce qui est au-delà, extérieur à un domaine ; immanent, ce qui est contenu en lui.", "Pour certaines religions, Dieu est transcendant au monde ; pour Spinoza, Dieu est immanent à la nature."],
  ["Médiat / immédiat", "Immédiat : sans intermédiaire ; médiat : qui passe par un intermédiaire (raisonnement, signe).", "La perception est immédiate ; une démonstration est une connaissance médiate."],
  ["Idéal / réel", "L'idéal est ce qui n'existe que dans la pensée comme modèle ; le réel, ce qui existe effectivement.", "La cité juste de Platon est un idéal."],
  ["Essentiel / accidentel", "L'essentiel appartient à la nature d'une chose ; l'accidentel peut changer sans qu'elle cesse d'être ce qu'elle est.", "Être raisonnable est essentiel à l'homme ; avoir les cheveux bruns est accidentel."],
  ["Public / privé", "Est public ce qui concerne tous les citoyens ; privé, ce qui relève de l'individu ou de la famille.", "La laïcité distingue l'espace public et la conviction religieuse privée."],
];

MATIERES.push({
  cle: "philo", nom: "Philosophie", court: "Philo", labelChap: "Notion",
  sous: "Épreuve finale · 4 h · coef. 8",
  intro: "Les 17 notions du programme, les repères, la méthode de la dissertation et de l'explication de texte, et des sujets à analyser.",
  epreuve: `<p><b>Lundi 14 juin 2027, de 8 h à 12 h. Coefficient 8.</b> Trois sujets au choix : <b>deux dissertations</b> et <b>une explication de texte</b>. Tu en traites un seul.</p>
    <p>Les sujets portent sur les 17 notions du programme. Le texte à expliquer est d'un auteur de la liste du programme, et les sujets peuvent être accompagnés de questions qui aident à construire le travail.</p>
    <p>On évalue ta capacité à poser un problème, à construire une réflexion argumentée, à mobiliser des connaissances philosophiques et à t'exprimer clairement.</p>`,
  chapitres: NOTIONS,
  generes: [
    { titre: "Distinguer deux repères", niv: 2, ch: null, gen() {
        const [r, d, ex] = pick(REPERES);
        return { q: `<p>Le programme de philosophie comprend des <b>repères</b>, des distinctions conceptuelles à maîtriser.</p><p>Définis et distingue : <b>${r}</b>. Donne un exemple.</p>`, c: `<p>${d}</p><p><b>Exemple :</b> ${ex}</p><p>Dans une copie, utiliser un repère permet de clarifier un problème : par exemple, « le juste se réduit-il au légal ? » repose sur la distinction légal / légitime.</p>` };
    } },
    { titre: "Trouver le problème d'un sujet", niv: 3, ch: null, gen() {
        const n = pick(NOTIONS), e = pick(n.exos);
        return { q: e.q.replace("Définis les termes, formule une problématique et propose un plan en deux ou trois parties.", "Repère le paradoxe ou la tension que contient ce sujet, puis formule une problématique en une ou deux phrases."), c: e.c };
    } },
  ],
  methode: [
    { titre: "La dissertation", html: `
<p>La dissertation répond à une <b>question</b> par une réflexion <b>argumentée</b>, qui examine plusieurs réponses possibles avant d'aboutir à une position.</p>
<ol><li><b>Analyser le sujet (30 min)</b> : définir chaque terme, repérer la notion du programme concernée, chercher les présupposés de la question.</li>
<li><b>Trouver le problème</b> : pourquoi la question se pose-t-elle ? Quelle tension y a-t-il entre deux réponses possibles ? La problématique formule cette tension.</li>
<li><b>Construire un plan progressif</b> en 2 ou 3 parties : on ne juxtapose pas « oui / non », on approfondit. Chaque partie s'appuie sur des arguments, des exemples et des références philosophiques.</li>
<li><b>Rédiger</b> l'introduction et la conclusion au brouillon, puis le développement directement au propre.</li></ol>
${box("L'introduction", "1. Une <b>accroche</b> (exemple, situation, opinion courante). 2. L'<b>analyse des termes</b>. 3. La <b>problématique</b>, qui fait apparaître la difficulté. 4. L'<b>annonce du plan</b>.")}
${box("Utiliser un auteur", "Ne récite pas une doctrine : explique la thèse en tes mots et montre en quoi elle répond au problème. Une référence bien expliquée vaut mieux que cinq noms cités.", "tip")}
${box("Erreurs à éviter", "Réciter un cours, répondre par oui ou par non dès l'introduction, faire un catalogue d'auteurs, oublier de définir les termes, une conclusion qui ne répond pas.", "warn")}` },
    { titre: "L'explication de texte", html: `
<p>Expliquer un texte, c'est en dégager le <b>problème</b>, la <b>thèse</b> et la <b>démarche argumentative</b>, puis en discuter la portée.</p>
<ol><li><b>Lire plusieurs fois</b> le texte et repérer la thèse (souvent au début ou à la fin), les connecteurs logiques et les exemples.</li>
<li><b>Dégager le problème</b> auquel le texte répond et l'enjeu.</li>
<li><b>Découper le texte</b> en 2 ou 3 moments selon le mouvement de l'argumentation.</li>
<li><b>Expliquer</b> chaque moment ligne à ligne : définir les mots importants, reformuler, expliquer les exemples, montrer comment l'auteur avance.</li>
<li><b>Discuter</b> (dans le développement ou à la fin) : intérêt de la thèse, limites, objections possibles.</li></ol>
${box("L'introduction", "Le thème, le problème, la thèse de l'auteur, l'enjeu, et l'annonce des étapes du texte.")}
${box("Erreur la plus fréquente", "La paraphrase : répéter le texte avec d'autres mots. Il faut expliquer <b>pourquoi</b> l'auteur dit cela et <b>comment</b> il le justifie.", "warn")}` },
    { titre: "Les repères du programme", html: `<p>Ces distinctions conceptuelles aident à analyser un sujet. Entraîne-toi avec l'exercice « Distinguer deux repères » dans l'onglet Exercices.</p><ul>${REPERES.map(([r, d]) => `<li><b>${r}</b> : ${d}</li>`).join("")}</ul>` },
  ],
  sujets: [
    { titre: "Série 1", type: "Dissertation", q: "<p>Choisis l'un des deux sujets :</p><ol><li>Peut-on être libre sans les autres ?</li><li>La technique nous éloigne-t-elle de la nature ?</li></ol>",
      c: `<p><b>Sujet 1. Problématique :</b> les autres sont-ils un obstacle à ma liberté (contraintes, regard, lois) ou la condition de son existence ?</p>${plan("Les autres limitent ma liberté : contraintes sociales, regard d'autrui, lois.", "Mais seul, l'homme n'est pas libre : il dépend de la nature et de ses passions ; c'est la société et le contrat qui fondent la liberté civile (Rousseau).", "La liberté est relationnelle : reconnaissance mutuelle, éducation et vie politique la rendent possible.")}<p><b>Sujet 2. Problématique :</b> en transformant la nature, la technique nous en sépare-t-elle ou exprime-t-elle notre propre nature ?</p>${plan("La technique crée un monde artificiel et domine la nature (Descartes, Heidegger : arraisonnement).", "Mais elle est naturelle à l'homme, être démuni qui doit compenser sa faiblesse (Prométhée, Aristote, Bergson).", "Elle peut aussi nous aider à connaître et protéger la nature, si elle est guidée par une éthique de la responsabilité (Jonas).")}` },
    { titre: "Série 2", type: "Dissertation", q: "<p>Choisis l'un des deux sujets :</p><ol><li>La vérité peut-elle être dangereuse ?</li><li>Le travail rend-il heureux ?</li></ol>",
      c: `<p><b>Sujet 1. Problématique :</b> la vérité est une valeur, mais sa recherche ou sa révélation peut-elle nuire aux individus ou à la société ?</p>${plan("La vérité peut blesser, détruire des illusions protectrices, menacer l'ordre établi (Socrate condamné).", "Mais l'ignorance et le mensonge sont plus dangereux : ils nous rendent manipulables (caverne de Platon).", "Le danger vient de l'usage de la vérité : il faut la chercher et la dire avec prudence et respect.")}<p><b>Sujet 2. Problématique :</b> le travail, nécessaire et souvent pénible, peut-il être une source de bonheur ?</p>${plan("Le travail est une contrainte, souvent pénible, et l'aliénation peut le rendre malheureux (Marx, Simone Weil).", "Mais il permet de se réaliser, d'être reconnu et de transformer le monde (Hegel).", "Le bonheur au travail dépend de ses conditions et de son sens ; il n'est pas le tout du bonheur.")}` },
    { titre: "Série 3", type: "Dissertation", q: "<p>Choisis l'un des deux sujets :</p><ol><li>L'État doit-il faire notre bonheur ?</li><li>Avons-nous besoin d'art ?</li></ol>",
      c: `<p><b>Sujet 1. Problématique :</b> le rôle de l'État est-il de rendre les citoyens heureux, ou seulement de garantir leur sécurité et leurs droits ?</p>${plan("L'État doit assurer les conditions du bonheur : sécurité, santé, éducation (État-providence).", "Mais un État qui impose une conception du bonheur devient paternaliste, voire totalitaire (Kant : le despotisme paternaliste) ; le bonheur est affaire privée.", "L'État doit garantir la justice et la liberté, qui permettent à chacun de chercher son bonheur.")}<p><b>Sujet 2. Problématique :</b> l'art, qui n'est pas utile au sens vital, répond-il pourtant à un besoin humain ?</p>${plan("L'art semble superflu : il ne répond à aucun besoin vital.", "Mais il répond à des besoins proprement humains : connaissance du réel (Bergson), expression de l'esprit (Hegel), purification des passions (Aristote).", "Le besoin d'art montre que l'homme ne se réduit pas à ses besoins biologiques.")}` },
  ],
});
}
